function buildOrderLink(branch, table, mode = "dine-in") {
  const base = window.location.origin + window.location.pathname;
  const params = new URLSearchParams({
    mode,
    branch
  });
  if (table) params.set("table", table);
  return `${base}?${params.toString()}`;
}
function loadImg(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}
function roundRectPath(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
function wrapCenteredText(ctx, text, cx, y, maxWidth, lineHeight) {
  if (!text) return y;
  const words = text.split(" ");
  let line = "";
  const lines = [];
  words.forEach(w => {
    const test = line ? line + " " + w : w;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = w;
    } else line = test;
  });
  if (line) lines.push(line);
  lines.forEach(ln => {
    ctx.fillText(ln, cx, y);
    y += lineHeight;
  });
  return y;
}
function measureWrappedLines(ctx, text, maxWidth) {
  if (!text) return 0;
  const words = text.split(" ");
  let line = "";
  let count = 0;
  words.forEach(w => {
    const test = line ? line + " " + w : w;
    if (ctx.measureText(test).width > maxWidth && line) {
      count++;
      line = w;
    } else line = test;
  });
  if (line) count++;
  return count;
}
async function drawQrCard({
  url,
  topText,
  bottomText,
  table,
  showLogo
}) {
  const W = 640;
  const qrSize = 400;
  // Đo trước để tính đúng chiều cao cần thiết, tránh dư khoảng trắng phía dưới.
  const measureCanvas = document.createElement("canvas");
  const mctx = measureCanvas.getContext("2d");
  mctx.font = "bold 34px sans-serif";
  const topLines = measureWrappedLines(mctx, topText, W - 100);
  mctx.font = "22px sans-serif";
  const bottomLines = measureWrappedLines(mctx, bottomText, W - 110);
  let y = 80;
  if (topText) y += topLines * 44 + 16;
  y += qrSize + 56;
  if (table) y += 60;
  const bottomBlockHeight = bottomText ? bottomLines * 30 : 0;
  const H = y + bottomBlockHeight + (bottomText ? 24 : 40);
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#FFFFFF";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.textAlign = "center";
  y = 80;
  if (topText) {
    ctx.fillStyle = "#57423D";
    ctx.font = "bold 34px sans-serif";
    y = wrapCenteredText(ctx, topText, W / 2, y, W - 100, 44) + 16;
  }
  const qrCanvas = document.createElement("canvas");
  await new Promise((resolve, reject) => {
    QRCode.toCanvas(qrCanvas, url, {
      width: qrSize,
      margin: 1,
      errorCorrectionLevel: "H",
      color: {
        dark: "#361E14",
        light: "#FFFFFF"
      }
    }, err => err ? reject(err) : resolve());
  });
  const qrX = (W - qrSize) / 2;
  ctx.drawImage(qrCanvas, qrX, y, qrSize, qrSize);
  if (showLogo) {
    try {
      const logoImg = await loadImg(LOGO_URL);
      const logoBox = qrSize * 0.26;
      const lx = qrX + (qrSize - logoBox) / 2;
      const ly = y + (qrSize - logoBox) / 2;
      ctx.fillStyle = "#FFFFFF";
      roundRectPath(ctx, lx - 10, ly - 10, logoBox + 20, logoBox + 20, 14);
      ctx.fill();
      ctx.save();
      ctx.beginPath();
      ctx.arc(lx + logoBox / 2, ly + logoBox / 2, logoBox / 2, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(logoImg, lx, ly, logoBox, logoBox);
      ctx.restore();
    } catch (e) {/* bỏ qua nếu logo lỗi */}
  }
  y += qrSize + 56;
  if (table) {
    ctx.fillStyle = "#A83E28";
    ctx.font = "bold 44px sans-serif";
    ctx.fillText(`BÀN ${table}`, W / 2, y);
    y += 60;
  }
  if (bottomText) {
    ctx.fillStyle = "#7D6E63";
    ctx.font = "22px sans-serif";
    wrapCenteredText(ctx, bottomText, W / 2, y, W - 110, 30);
  }
  return canvas;
}
