function slugify(text) {
  return (text || "").toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "") // bỏ dấu tiếng Việt
  .replace(/đ/gi, "d").toLowerCase().trim().replace(/[^a-z0-9\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
}

