// ---- tồn kho theo từng chi nhánh (branchStock là mảng {branch, productId, stock}) ----
function stockOf(branchStock, branch, productId) {
  const row = branchStock.find(r => r.branch === branch && r.productId === productId);
  return row ? row.stock : 0;
}
function totalStockOf(branchStock, productId) {
  return branchStock.filter(r => r.productId === productId).reduce((s, r) => s + r.stock, 0);
}
function withStockDelta(branchStock, branch, productId, delta) {
  const idx = branchStock.findIndex(r => r.branch === branch && r.productId === productId);
  if (idx === -1) return delta <= 0 ? branchStock : [...branchStock, {
    branch,
    productId,
    stock: Math.max(0, delta)
  }];
  const next = [...branchStock];
  next[idx] = {
    ...next[idx],
    stock: Math.max(0, next[idx].stock + delta)
  };
  return next;
}
function withStockSet(branchStock, branch, productId, value) {
  const idx = branchStock.findIndex(r => r.branch === branch && r.productId === productId);
  const stock = Math.max(0, Number(value) || 0);
  if (idx === -1) return [...branchStock, {
    branch,
    productId,
    stock
  }];
  const next = [...branchStock];
  next[idx] = {
    ...next[idx],
    stock
  };
  return next;
}
function withStockDeltas(branchStock, branch, items) {
  let bs = branchStock;
  items.forEach(it => {
    bs = withStockDelta(bs, branch, it.id, -it.qty);
  });
  return bs;
}
async function replaceTable(table, rows, toDb, shopId) {
  await sb.from(table).delete().eq("shop_id", shopId);
  if (rows.length) await sb.from(table).insert(rows.map(r => ({
    ...toDb(r),
    shop_id: shopId
  })));
}
async function replaceBranchStock(rows, shopId) {
  await sb.from("branch_stock").delete().eq("shop_id", shopId);
  if (rows.length) await sb.from("branch_stock").insert(rows.map(r => ({
    ...branchStockToDb(r),
    shop_id: shopId
  })));
}
// Ghi 1 dòng tồn kho trực tiếp (atomic), KHÔNG xoá/chèn lại cả bảng — tránh việc
// một client khác đọc phải bảng đang rỗng giữa lúc xoá và chèn.
async function upsertStockRow(shopId, branch, productId, stock) {
  const {
    error
  } = await sb.from("branch_stock").upsert({
    shop_id: shopId,
    branch,
    product_id: productId,
    stock: Math.max(0, stock)
  }, {
    onConflict: "shop_id,branch,product_id"
  });
  if (error) console.error("upsert branch_stock", error);
}
async function upsertStockRows(shopId, branchStockSnapshot, branch, deltasByProductId) {
  const entries = Object.entries(deltasByProductId);
  await Promise.all(entries.map(([productId, delta]) => upsertStockRow(shopId, branch, productId, stockOf(branchStockSnapshot, branch, productId) + delta)));
}

