function seedOrders(branches, staff) {
  const out = [];
  for (let d = 6; d >= 0; d--) {
    const date = new Date();
    date.setDate(date.getDate() - d);
    const n = 2 + Math.floor(Math.random() * 4);
    for (let i = 0; i < n; i++) {
      const items = SEED_PRODUCTS.filter(() => Math.random() > 0.55).slice(0, 3).map(p => ({
        id: p.id,
        name: p.name,
        category: p.category,
        price: p.price,
        costPrice: costTotal(p),
        qty: 1 + Math.floor(Math.random() * 3)
      }));
      if (!items.length) continue;
      const subtotal = items.reduce((s, it) => s + it.price * it.qty, 0);
      const discount = Math.random() > 0.8 ? {
        type: "percent",
        value: 10
      } : {
        type: "amount",
        value: 0
      };
      const discountAmount = discount.type === "percent" ? Math.round(subtotal * discount.value / 100) : discount.value;
      const total = subtotal - discountAmount;
      const pm = PAYMENT_METHODS[Math.floor(Math.random() * PAYMENT_METHODS.length)].key;
      out.push({
        id: uid(),
        branch: branches[Math.floor(Math.random() * branches.length)],
        items,
        subtotal,
        discount,
        discountAmount,
        total,
        paymentMethod: pm,
        staffName: staff[Math.floor(Math.random() * staff.length)].name,
        status: "completed",
        createdAt: new Date(date.getTime() - i * 3600000).toISOString()
      });
    }
  }
  return out;
}
